 reportPaths=['qa/vertical-and-guide-review.json','qa/horizontal-and-guide-review.json','qa/west-and-guide-review.json','tone-v1/review.json','tone-v2-local/review.json','geometry-v2/review.json','geometry-v3-local/review.json','geometry-v4-local/review.json','west-repair/v3/review.json']
